void append_checksum_to_message(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb || !msg) {
        return;
    }

    if (skb->ip_summed != CHECKSUM_NONE) {
        return;
    }

    int data_len = skb->len - tlen;
    if (offset >= data_len) {
        return;
    }

    int checksum_len = (offset >= 0) ? (data_len - offset) : data_len;

    __sum16 checksum = 0;
    const void *data = skb->data + tlen + offset;
    int i;

    for (i = 0; i < checksum_len; i += 2) {
        checksum += get_unaligned((__be16 *)(data + i));
    }

    if (checksum_len % 2 != 0) {
        checksum += ((__be16)0) << 8;
    }

    checksum = (checksum >> 16) + (checksum & 0xFFFF);
    checksum += (checksum >> 16);
    checksum = ~checksum;

    msg->msg_control = &checksum;
    msg->msg_controllen = sizeof(checksum);
}
